import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import ArrowCircleLeftIcon from '@mui/icons-material/ArrowCircleLeft';
import ArrowCircleRightIcon from '@mui/icons-material/ArrowCircleRight';
import CheckIcon from '@mui/icons-material/Check';
import { Box } from '@mui/material';

import GameEnd from 'components/game/GameEnd';
import GameProgress from 'components/game/GameProgress';
import GameQuestion from 'components/game/GameQuestion';
import MainButton from 'components/ui/MainButton';
import { GameUtil } from 'model/game/GameUtil';
import { gameAnswer, gameNewQuestion, gameNext, newGame } from 'store/actions';
import { useCurrentGame } from 'store/selector';
import { pxToRem } from 'util/util';

const styles = {
    main: {
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'column',
        justifyContent: 'space-between',
        width: '100%',
    },
};

const Game = () => {
    const dispatch = useDispatch();
    const { t } = useTranslation();
    const game = useCurrentGame();

    const [isInTransition, setIsInTransition] = useState(false);

    useEffect(() => {
        if (game && game.currentPhase === 0 && !isInTransition) {
            setIsInTransition(true);
            setTimeout(() => {
                setIsInTransition(false);
                dispatch(gameNewQuestion());
            }, 100);
        }
    }, [game, isInTransition, dispatch]);

    if (!game) {
        return null;
    }

    const phase = game.currentPhase;
    const isEnd = GameUtil.getIsEnd(game);
    const question = game && GameUtil.getQuestion(game);
    const isMapCountry = question && question.questionTypeKey === 'map_country';

    const handleConfirm = () => {
        if (phase === 1.5) {
            dispatch(gameAnswer(game.chosenAnswer));
        }
    };
    const handleNext = () => {
        if (phase === 2) {
            dispatch(gameNext());
        }
    };
    const handleClickHome = () => {
        dispatch(newGame());
    };

    // console.log('game render');

    return (
        <Box {...styles.main} flexGrow="1">
            {isEnd ? (
                <GameEnd />
            ) : (
                <>
                    <GameProgress />
                    <GameQuestion />
                </>
            )}
            <Box {...styles.main} margin={`${pxToRem(24)} 0`}>
                {isEnd ? (
                    <MainButton
                        buttonP={{
                            color: 'success',
                            size: 'large',
                            onClick: handleClickHome,
                            startIcon: <ArrowCircleLeftIcon />,
                        }}>
                        {t('Home')}
                    </MainButton>
                ) : isMapCountry && phase < 2 ? (
                    <MainButton
                        buttonP={{
                            color: phase === 1.5 ? 'primary' : 'success',
                            size: 'large',
                            disabled: phase < 1.5,
                            onClick: handleConfirm,
                        }}
                        typoP={{
                            fontSize: pxToRem(20),
                            fontWeight: '700',
                        }}>
                        <CheckIcon fontSize="large" />
                    </MainButton>
                ) : (
                    <MainButton
                        buttonP={{
                            color: 'success',
                            size: 'large',
                            disabled: phase < 2,
                            onClick: handleNext,
                            endIcon: <ArrowCircleRightIcon />,
                        }}
                        typoP={{
                            fontSize: pxToRem(20),
                            fontWeight: '700',
                        }}>
                        {t(GameUtil.getNextKeyLabel(game))}
                    </MainButton>
                )}
            </Box>
        </Box>
    );
};

export default Game;
