import { DIFFICULTY_EXPERT, DIFFICULTY_NORMAL } from 'config/baseConfig';
import * as React from 'react';

import Map, { TILE_LIGHT_NO_LABELS, TILE_SATELLITE } from 'components/ui/Map';

const GameMap = (props) => {
    const {
        game,
        question,
        geoFileName,
        choices,
        geoFolder,
        initialMapHeight,
        useFullScreen,
        useClickMarker,
        markers,
        onMarkerSet,
        markerResult,
    } = props;

    const tileProviderKey = game.difficultyLevel === DIFFICULTY_EXPERT ? TILE_SATELLITE : TILE_LIGHT_NO_LABELS;
    const useBorderLines = game.difficultyLevel === DIFFICULTY_NORMAL && question.isType('map_country');

    return (
        <Map
            tileProviderKey={tileProviderKey}
            geoFileName={geoFileName}
            // choices={choices} // goes with stash
            geoFolder={geoFolder}
            useClickMarker={useClickMarker}
            useFullScreen={useFullScreen}
            initialMapHeight={initialMapHeight}
            markers={markers}
            onMarkerSet={onMarkerSet}
            markerResult={markerResult}
            useBorderLines={useBorderLines}
            maxZoom={14}
        />
    );
};

export default GameMap;
