import { useTheme } from '@emotion/react';
import { t } from 'i18next';
import * as React from 'react';
import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';

import CancelIcon from '@mui/icons-material/Cancel';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import CloseIcon from '@mui/icons-material/Close';
import InfoIcon from '@mui/icons-material/Info';
import { Box, Card, Grow, IconButton, Modal, Stack, Typography } from '@mui/material';

import GameButton from 'components/game/GameButton';
import GameMap from 'components/game/GameMap';
import GameFlag from 'components/ui/GameFlag';
import GamePicture from 'components/ui/GamePicture';
import CountryCard from 'components/wiki/CountryCard';
import LandmarkCard from 'components/wiki/LandmarkCard';
import PeakCard from 'components/wiki/PeakCard';
import SeaCard from 'components/wiki/SeaCard';
import { getEntityForKey } from 'data/ConfigGeoGo';
import { GameUtil } from 'model/game/GameUtil';
import { Question } from 'model/game/Question';
import { gameAnswer, gameSetAnswer } from 'store/actions';
import { useCurrentGame, useGameCategory, useGameConfig } from 'store/selector';
import { getGameSVG, getQuestionType, pxToRem } from 'util/util';

// preload images for next Question
const nextQuestionImages = (_game) => {
    const nextQuestion = GameUtil.getNextQuestion(_game);
    if (!nextQuestion) {
        return null;
    }
    if (nextQuestion.hasFlag || nextQuestion.hasAnswerFlag) {
        const countries =
            nextQuestion.answerProperty === 'cca3' && nextQuestion.choices
                ? nextQuestion.choices.map((choice) => choice.toLowerCase())
                : [nextQuestion.key.toLowerCase()];
        countries.forEach((c) => {
            var img = new Image();
            img.src = `${process.env.PUBLIC_URL}/assets/flagsAndGeo/svg/${c.toLowerCase()}.svg`;
        });
    } else if (nextQuestion.hasPicture) {
        var img = new Image();
        img.src = `${nextQuestion.questionText.src}`;
    }
    return null;
};

const GameQuestion = () => {
    const dispatch = useDispatch();
    const { i18n } = useTranslation();
    const theme = useTheme();
    const game = useCurrentGame();
    const gameCategory = useGameCategory();
    const gameConfig = useGameConfig();

    const [chosenAnswer, setChosenAnswer] = useState('');
    const [question, setQuestion] = useState();
    const [entityCardOpen, setEntityCardOpen] = useState(false);
    const [markerValue, setMarkerValue] = useState(undefined);

    useEffect(() => {
        nextQuestionImages(game);
        setQuestion(new Question(GameUtil.getQuestion(game)));
        setMarkerValue(undefined);
    }, [game.currentTurn]);

    if (!game || !question) {
        return;
    }
    const questionType = getQuestionType(gameConfig.questionTypes, question.questionTypeKey);
    const phase = game.currentPhase;
    // console.log(question);

    const handleChoiceClick = (_chosenAnswer) => {
        if (phase === 1) {
            setChosenAnswer(_chosenAnswer);
            dispatch(gameAnswer(_chosenAnswer));
        }
    };

    const handleMarkerSet = (isMarkerRight) => {
        setMarkerValue(isMarkerRight);
        dispatch(gameSetAnswer(isMarkerRight ? question.answer : ''));
    };

    const textReplace = (text, replacements) => {
        if (!replacements || replacements.length === 0) {
            return text;
        }
        replacements.forEach((rep, i) => {
            text = text.split('{' + i + '}').join(rep);
        });
        return text;
    };

    const handleClickOpenEntity = (event) => {
        setEntityCardOpen(true);
    };
    const handleCloseEntityCard = (event) => {
        setEntityCardOpen(false);
    };

    const entity = getEntityForKey(questionType.entityType, question.key);

    const questionPhrase = (
        <>
            <Typography
                {...(question.isType('unique_fact') ? { color: theme.palette.success.main } : null)}
                fontSize={pxToRem(20)}
                fontWeight="600"
                lineHeight={pxToRem(22)}
                mb={questionType.questionPhraseInverted ? 0 : pxToRem(16)}
                mt={questionType.questionPhraseInverted ? pxToRem(16) : 0}
                mx={pxToRem(10)}
                sx={{
                    '&:first-of-type': {
                        mt: 0,
                    },
                    '&:last-child': {
                        mb: 0,
                    },
                }}>
                {textReplace(questionType.questionPhrase[i18n.language], question.questionPhraseValues)}
            </Typography>
            {questionType.questionSubPhrase && (
                <Typography fontSize={pxToRem(12)} fontWeight="400" lineHeight={pxToRem(12)} mt={pxToRem(12)} mb="0">
                    {questionType.questionSubPhrase[i18n.language]}
                </Typography>
            )}
        </>
    );

    const choiceButtons = (
        <>
            {GameUtil.isFlashcard(game) ? (
                <ChoiceButton
                    game={game}
                    question={question}
                    handleChoiceClick={handleChoiceClick}
                    chosenAnswer={chosenAnswer}
                    choice={question.answer}
                    index={1}
                    isFlag={false}
                />
            ) : question.choices ? (
                question.choices.map((choice, index) => (
                    <ChoiceButton
                        key={index}
                        game={game}
                        question={question}
                        handleChoiceClick={handleChoiceClick}
                        chosenAnswer={chosenAnswer}
                        choice={choice}
                        index={index}
                        isFlag={question.questionTypeKey === 'flag'}
                    />
                ))
            ) : null}
        </>
    );

    const getInfoButton = () => {
        return phase === 2 && entity ? (
            <IconButton
                aria-label={t('Info')}
                onClick={handleClickOpenEntity}
                sx={{
                    color: theme.palette.text.main,
                    // p: 1.8,
                    position: 'absolute',
                    ...(questionType.hasQuestionMap
                        ? { top: pxToRem(0) }
                        : questionType.hasPicture
                          ? { top: pxToRem(14) }
                          : { bottom: 0 }),
                    right: 0,
                    zIndex: 400,
                    ...(questionType.hasQuestionMap && GameUtil.isExpert(game)
                        ? { color: '#fff', filter: 'drop-shadow(0px 2px 2px rgba(0, 0, 0, 0.3))' }
                        : null),
                }}>
                <InfoIcon />
            </IconButton>
        ) : null;
    };

    const hasMap = questionType.hasQuestionMap || questionType.hasAnswerMap;
    let markerResult = '';
    if (phase === 2) {
        markerResult = questionType.hasAnswerMap ? (markerValue ? 'success' : 'error') : undefined;
    }

    return (
        <>
            <Stack
                alignItems="center"
                flexDirection="column"
                justifyContent="center"
                spacing={2}
                sx={{
                    flexGrow: 1,
                    width: '100%',
                    position: 'relative',
                }}>
                {!questionType.hasQuestionMap && (
                    <Grow in={phase > 0} timeout={200} key={question.questionText}>
                        <Card
                            sx={{
                                px: 2,
                                ...(questionType.hasPicture ? { pt: 3, pb: 2 } : { pt: 4, pb: 4 }),
                                textAlign: 'center',
                                width: '100%',
                                boxSizing: 'border-box',
                                position: 'relative',
                            }}>
                            <Box
                                sx={{
                                    display: 'block',
                                    position: 'absolute',
                                    top: 0,
                                    left: 0,
                                    zIndex: 0,
                                    width: '100%',
                                    height: '100%',
                                    right: 0,
                                    svg: {
                                        color: theme.palette.neutral[200],
                                        height: pxToRem(140),
                                        width: pxToRem(140),
                                        fill: 'currentColor',
                                        position: 'absolute',
                                        // opacity: 0.1,
                                        left: pxToRem(10),
                                        ...(question.isType('country_flag')
                                            ? { bottom: pxToRem(-5) }
                                            : { bottom: pxToRem(-20) }),
                                        transform: 'rotate(-10deg)',
                                        opacity: 0.5,
                                    },
                                }}>
                                {getGameSVG(gameCategory?.key ?? undefined)}
                            </Box>
                            <Box
                                sx={{
                                    zIndex: 1,
                                    position: 'relative',
                                    overflow: 'visible',
                                }}>
                                {!questionType.questionPhraseInverted && <>{questionPhrase}</>}
                                {question.isType('country_flag') ? (
                                    <GameFlag
                                        country={question.key}
                                        svgOverrides={{
                                            width: '90%',
                                            maxWidth: pxToRem(180),
                                            maxHeight: pxToRem(100),
                                            filter: 'drop-shadow(0px 4px 4px rgba(0, 0, 0, 0.3))',
                                        }}
                                    />
                                ) : questionType.hasPicture ? (
                                    <>
                                        <GamePicture
                                            image={question.questionText}
                                            altText={t('Peak')}
                                            inGame={true}
                                            phase={phase}
                                        />
                                        {question.isType('country_landmark') && question.questionAdditionnalText && (
                                            <Typography
                                                color="success.main"
                                                fontSize={pxToRem(24)}
                                                fontWeight="800"
                                                lineHeight={pxToRem(28)}
                                                mt={pxToRem(16)}>
                                                {phase >= 2 ? question.questionAdditionnalText : '???'}
                                            </Typography>
                                        )}
                                    </>
                                ) : question.questionFullText || question.questionText ? (
                                    <Typography
                                        {...(question.isType('unique_fact')
                                            ? {
                                                  color: theme.palette.text.main,
                                                  fontSize: pxToRem(20),
                                                  fontWeight: '500',
                                                  lineHeight: pxToRem(22),
                                              }
                                            : {
                                                  color: theme.palette.success.main,
                                                  fontSize: pxToRem(24),
                                                  fontWeight: '800',
                                                  lineHeight: pxToRem(28),
                                              })}>
                                        {question
                                            ? phase >= 2
                                                ? question.questionFullText ?? question.questionText
                                                : question.questionText
                                            : ''}
                                    </Typography>
                                ) : null}
                                {questionType.questionPhraseInverted && <>{questionPhrase}</>}
                            </Box>
                            {getInfoButton()}
                        </Card>
                    </Grow>
                )}
                {hasMap && (
                    <Grow in={phase > 0} timeout={200} key={question.questionText + '_map'}>
                        <Card
                            sx={{
                                p: 0,
                                textAlign: 'center',
                                width: '100%',
                                boxSizing: 'border-box',
                                position: 'relative',
                                border: 1,
                                borderColor: theme.palette.neutral[100],
                                height: questionType.hasAnswerMap ? '45vh' : '32vh',
                                // maxHeight: '450px',
                            }}>
                            <GameMap
                                game={game}
                                question={question}
                                geoFileName={
                                    !questionType.mapUseCoordinates
                                        ? question.isType('sea_map')
                                            ? question.key
                                            : question.key.toLowerCase()
                                        : undefined
                                }
                                choices={question.choices}
                                geoFolder={
                                    !questionType.mapUseCoordinates
                                        ? question.isType('sea_map')
                                            ? 'geoSeas'
                                            : 'geo'
                                        : undefined
                                }
                                markers={questionType.mapUseCoordinates ? [question.questionText] : undefined}
                                useClickMarker={questionType.hasAnswerMap}
                                useFullScreen={questionType.hasAnswerMap}
                                initialMapHeight={questionType.hasAnswerMap ? '45vh' : '32vh'}
                                onMarkerSet={handleMarkerSet}
                                markerResult={markerResult}
                            />
                            {questionType.hasQuestionMap && (
                                <>
                                    <Card
                                        elevation={10}
                                        sx={{
                                            position: 'absolute',
                                            top: 0,
                                            left: '50%',
                                            transform: 'translateX(-50%)',
                                            zIndex: 1000,
                                            textAlign: 'center',
                                            width: '100%',
                                            boxSizing: 'border-box',
                                            width: 'max-content',
                                            display: 'block',
                                            borderTopRightRadius: '0',
                                            borderTopLeftRadius: '0',
                                            padding: 0,

                                            '.MuiTypography-root': {
                                                padding: `${pxToRem(8)} ${pxToRem(16)} ${pxToRem(8)}`,
                                                marginLeft: 0,
                                                marginRight: 0,
                                            },
                                        }}>
                                        {questionPhrase}
                                    </Card>
                                    {getInfoButton()}
                                </>
                            )}
                            {phase === 2 && questionType.hasAnswerMap && (
                                <Box
                                    sx={{
                                        position: 'absolute',
                                        zIndex: 1001,
                                        backgroundColor: `${theme.palette[markerResult].main}`,
                                        left: -1,
                                        bottom: -1,
                                        borderBottomLeftRadius: pxToRem(15),
                                        borderTopRightRadius: pxToRem(15),
                                        width: pxToRem(40),
                                        height: pxToRem(40),
                                        display: 'flex',
                                        justifyContent: 'center',
                                        alignItems: 'center',
                                        filter: 'drop-shadow(-1px -1px 2px rgba(0, 0, 0, 0.2))',
                                        svg: {
                                            color: theme.palette.primary.contrastText,
                                        },
                                    }}>
                                    {markerResult === 'success' ? <CheckCircleIcon /> : <CancelIcon />}
                                </Box>
                            )}
                        </Card>
                    </Grow>
                )}

                {question.isType('flag') ? (
                    <Stack
                        direction="row"
                        flexWrap="wrap"
                        spacing={2}
                        useFlexGap
                        sx={{
                            width: '100%',
                        }}>
                        {choiceButtons}
                    </Stack>
                ) : questionType.hasAnswerMap ? null : (
                    <>{choiceButtons}</>
                )}
            </Stack>
            {entity && (
                <Modal
                    open={entityCardOpen}
                    onClose={handleCloseEntityCard}
                    aria-labelledby="modal-modal-title"
                    aria-describedby="modal-modal-description">
                    <Box
                        position="relative"
                        sx={{
                            width: '90vw',
                            height: '80vh',
                            maxWidth: (theme) => {
                                return {
                                    xs: theme.breakpoints.values.sm,
                                    sm: theme.breakpoints.values.sm,
                                    md: theme.breakpoints.values.md,
                                };
                            },
                        }}>
                        {entity.isCountry ? (
                            <CountryCard country={entity} />
                        ) : entity.isPeak ? (
                            <PeakCard peak={entity} />
                        ) : entity.isLandmark ? (
                            <LandmarkCard landmark={entity} />
                        ) : entity.isWater ? (
                            <SeaCard sea={entity} />
                        ) : (
                            <></>
                        )}
                        <IconButton
                            className="standalone"
                            aria-label={t('Close')}
                            onClick={handleCloseEntityCard}
                            color="text"
                            sx={{
                                position: 'absolute',
                                right: pxToRem(16),
                                top: pxToRem(20),
                            }}>
                            <CloseIcon />
                        </IconButton>
                    </Box>
                </Modal>
            )}
        </>
    );
};

export default GameQuestion;

const ChoiceButton = (props) => {
    const { game, question, handleChoiceClick, chosenAnswer, choice, index, isFlag } = props;
    const theme = useTheme();
    const gameConfig = useGameConfig();
    // console.log(question);
    const questionType = getQuestionType(gameConfig.questionTypes, question.questionTypeKey);
    const phase = game.currentPhase;
    const rightAnswer = question.getRightAnswer();
    const choiceText = choice?.label ? choice?.label : choice;
    const choiceValue = choice?.value ? choice?.value : choice;
    const choiceTextWithInfo = (
        <>
            {choiceText}
            {choice?.additionalLabel && (
                <>
                    &nbsp;-&nbsp;<small>{choice?.additionalLabel}</small>
                </>
            )}
        </>
    );
    return (
        <Grow in={phase > 0} timeout={index * 75 + 200} key={question.id + index} easing="linear">
            <Box width={isFlag ? `calc(50% - 12px)` : '100%'} minHeight={isFlag ? '126px' : 'auto'}>
                <GameButton
                    onClick={() => {
                        handleChoiceClick(choiceValue);
                    }}
                    key={choiceText + index}
                    phase={phase}
                    choice={choiceValue}
                    rightAnswer={rightAnswer}
                    chosenAnswer={chosenAnswer}
                    isFlag={isFlag}
                    answerAdditionnalText={question.answerAdditionnalText}>
                    {isFlag ? (
                        <>
                            {GameUtil.isFlashcard(game) && phase < 2 ? (
                                ' * * * '
                            ) : (
                                <GameFlag
                                    country={choiceValue}
                                    // mask={phase < 2 && GameUtil.isExpert(game)}
                                    svgOverrides={{
                                        width: '100%',
                                        maxWidth: 'fit-content',
                                        maxHeight: pxToRem(80),
                                        filter: 'drop-shadow(0px 4px 4px rgba(0, 0, 0, 0.3))',
                                    }}
                                />
                            )}
                        </>
                    ) : (
                        <>
                            {phase < 2
                                ? GameUtil.isExpert(game) && questionType.hasExpertAnswerHidden
                                    ? choiceText[0] + ' * * * ' + choiceText[choiceText.length - 1]
                                    : GameUtil.isFlashcard(game) && phase < 2
                                      ? ' * * * '
                                      : choiceTextWithInfo
                                : choiceTextWithInfo}
                        </>
                    )}
                </GameButton>
            </Box>
        </Grow>
    );
};
